/// <summary>
///     Lists all credentials stored in the YubiHSM Auth applet.
/// </summary>
/// <param name="cancellationToken">Cancellation token.</param>
/// <returns>A read-only list of stored credentials.</returns>
Task<IReadOnlyList<HsmAuthCredential>> ListCredentialsAsync(
    CancellationToken cancellationToken = default);

/// <summary>
///     Deletes a credential from the YubiHSM Auth applet.
/// </summary>
/// <param name="managementKey">The borrowed 16-byte management key. The caller must clear it after use.</param>
/// <param name="label">The label of the credential to delete.</param>
/// <param name="cancellationToken">Cancellation token.</param>
/// <exception cref="HsmAuthRetryException">
///     The management key is incorrect. <see cref="HsmAuthRetryException.RetriesRemaining" />
///     reports the remaining management key attempts.
/// </exception>
Task DeleteCredentialAsync(
    ReadOnlyMemory<byte> managementKey,
    string label,
    CancellationToken cancellationToken = default);

/// <summary>
///     Gets the number of remaining management key retries.
/// </summary>
/// <param name="cancellationToken">Cancellation token.</param>
/// <returns>The number of remaining retries.</returns>
Task<int> GetManagementKeyRetriesAsync(CancellationToken cancellationToken = default);

/// <summary>
///     Changes the management key.
/// </summary>
/// <param name="currentManagementKey">The borrowed current 16-byte management key. The caller must clear it after use.</param>
/// <param name="newManagementKey">The borrowed new 16-byte management key. The caller must clear it after use.</param>
/// <param name="cancellationToken">Cancellation token.</param>
/// <exception cref="HsmAuthRetryException">
///     The current management key is incorrect. <see cref="HsmAuthRetryException.RetriesRemaining" />
///     reports the remaining management key attempts.
/// </exception>
Task PutManagementKeyAsync(
    ReadOnlyMemory<byte> currentManagementKey,
    ReadOnlyMemory<byte> newManagementKey,
    CancellationToken cancellationToken = default);

/// <summary>
///     Stores an asymmetric (EC P256) credential with an explicit private key.
///     Requires firmware 5.6.0+.
/// </summary>
/// <param name="managementKey">The borrowed 16-byte management key. The caller must clear it after use.</param>
/// <param name="label">The credential label (1-64 UTF-8 bytes).</param>
/// <param name="privateKey">The borrowed 32-byte EC P256 private key. The caller must clear it after use.</param>
/// <param name="credentialPassword">
///     The borrowed UTF-8 encoded credential password, at most 16 bytes. Shorter values are
///     null-padded to 16 bytes in an internal copy. The caller must clear the input after use.
/// </param>
/// <param name="touchRequired">Whether touch is required to use this credential.</param>
/// <param name="cancellationToken">Cancellation token.</param>
/// <exception cref="HsmAuthRetryException">
///     The management key is incorrect. <see cref="HsmAuthRetryException.RetriesRemaining" />
///     reports the remaining management key attempts.
/// </exception>
Task PutCredentialAsymmetricAsync(
    ReadOnlyMemory<byte> managementKey,
    string label,
    ReadOnlyMemory<byte> privateKey,
    ReadOnlyMemory<byte> credentialPassword,
    bool touchRequired = false,
    CancellationToken cancellationToken = default);

/// <summary>
///     Generates an asymmetric (EC P256) credential on-device.
///     The private key is generated by the YubiKey and never leaves the device.
///     Requires firmware 5.6.0+.
/// </summary>
/// <param name="managementKey">The borrowed 16-byte management key. The caller must clear it after use.</param>
/// <param name="label">The credential label (1-64 UTF-8 bytes).</param>
/// <param name="credentialPassword">
///     The borrowed UTF-8 encoded credential password, at most 16 bytes. Shorter values are
///     null-padded to 16 bytes in an internal copy. The caller must clear the input after use.
/// </param>
/// <param name="touchRequired">Whether touch is required to use this credential.</param>
/// <param name="cancellationToken">Cancellation token.</param>
/// <exception cref="HsmAuthRetryException">
///     The management key is incorrect. <see cref="HsmAuthRetryException.RetriesRemaining" />
///     reports the remaining management key attempts.
/// </exception>
Task GenerateCredentialAsymmetricAsync(
    ReadOnlyMemory<byte> managementKey,
    string label,
    ReadOnlyMemory<byte> credentialPassword,
    bool touchRequired = false,
    CancellationToken cancellationToken = default);

/// <summary>
///     Retrieves the public key for an asymmetric credential.
///     Requires firmware 5.6.0+.
/// </summary>
/// <param name="label">The credential label.</param>
/// <param name="cancellationToken">Cancellation token.</param>
/// <returns>The 65-byte uncompressed EC point (0x04 + x[32] + y[32]).</returns>
Task<ReadOnlyMemory<byte>> GetPublicKeyAsync(
    string label,
    CancellationToken cancellationToken = default);

/// <summary>
///     Lists all YubiHSM Auth credentials stored on the YubiKey.
///     Creates and disposes a session automatically.
/// </summary>
/// <param name="options">Optional cross-cutting session creation settings.</param>
/// <param name="cancellationToken">Cancellation token.</param>
/// <returns>A read-only list of stored credentials.</returns>
public async Task<IReadOnlyList<HsmAuthCredential>> ListHsmAuthCredentialsAsync(
    SessionCreationOptions? options = null,
    CancellationToken cancellationToken = default)
{
    await using var session = await yubiKey.CreateHsmAuthSessionAsync(
            options,
            cancellationToken: cancellationToken)
        .ConfigureAwait(false);

    return await session.ListCredentialsAsync(cancellationToken).ConfigureAwait(false);
}

public static async Task ListAsync(CancellationToken cancellationToken = default)
{
    OutputHelpers.WriteHeader("List Credentials");

    var selection = await DeviceSelector.SelectDeviceAsync(cancellationToken);
    if (selection is null) return;

    OutputHelpers.WriteActiveDevice(selection.DisplayName);

    await using var session = await selection.Device.CreateHsmAuthSessionAsync(
        cancellationToken: cancellationToken);
    await ListCredentials.RunAsync(session, cancellationToken);
}

public static async Task RunAsync(CancellationToken cancellationToken = default)
{
    OutputHelpers.WriteHeader("Factory Reset - YubiHSM Auth");

    var selection = await DeviceSelector.SelectDeviceAsync(cancellationToken);
    if (selection is null) return;

    OutputHelpers.WriteActiveDevice(selection.DisplayName);

    await using var session = await selection.Device.CreateHsmAuthSessionAsync(
        cancellationToken: cancellationToken);
    await ResetHsmAuth.RunAsync(session, cancellationToken);
}

public static class ListCredentials
{
    public static async Task RunAsync(
        HsmAuthSession session,
        CancellationToken cancellationToken = default)
    {
        var credentials = await session.ListCredentialsAsync(cancellationToken);

        if (credentials.Count == 0)
        {
            OutputHelpers.WriteInfo("No credentials stored.");
            return;
        }

        var table = HsmAuthHelpers.BuildCredentialsTable(credentials);

        AnsiConsole.Write(table);
        OutputHelpers.WriteInfo($"{credentials.Count} credential(s) found.");
    }
}

public static class GetManagementKeyRetries
{
    public static async Task RunAsync(
        HsmAuthSession session,
        CancellationToken cancellationToken = default)
    {
        var retries = await session.GetManagementKeyRetriesAsync(cancellationToken);

        OutputHelpers.WriteKeyValue("Management key retries remaining", retries.ToString());

        if (retries <= 3)
        {
            OutputHelpers.WriteWarning("Low retry count! Incorrect attempts will reduce this further.");
        }
    }
}

/// <summary>
/// Device selector for HsmAuth operations.
/// HsmAuth only supports SmartCard (CCID) transport.
/// In non-interactive mode, auto-selects the first available device.
/// </summary>
public sealed class HsmAuthDeviceSelector : DeviceSelectorBase
{
    /// <summary>
    /// Shared singleton instance.
    /// </summary>
    public static HsmAuthDeviceSelector Instance { get; } = new();

    /// <inheritdoc />
    protected override ConnectionType[] SupportedConnectionTypes { get; } =
    [
        ConnectionType.SmartCard
    ];

    /// <inheritdoc />
    protected override string SupportedTransportsDescription => "SmartCard (CCID)";

    /// <inheritdoc />
    protected override ConnectionType FindAllConnectionTypeFilter => ConnectionType.SmartCard;

    /// <inheritdoc />
    protected override IYubiKey? AutoSelectDevice(IReadOnlyList<IYubiKey> devices) =>
        devices[0];
}

public static class ResetHsmAuth
{
    public static async Task RunAsync(
        HsmAuthSession session,
        CancellationToken cancellationToken = default)
    {
        if (!OutputHelpers.ConfirmDestructive(
                "factory reset the YubiHSM Auth applet, deleting ALL stored credentials and resetting the management key"))
        {
            OutputHelpers.WriteInfo("Factory reset cancelled.");
            return;
        }

        await session.ResetAsync(cancellationToken);

        OutputHelpers.WriteSuccess("YubiHSM Auth applet reset to factory defaults.");
        OutputHelpers.WriteInfo("Management key has been reset to the default (all zeros).");
        OutputHelpers.WriteInfo("All credentials have been deleted.");
    }
}

/// <summary>
///     Validates and encodes a credential label to UTF-8 bytes.
/// </summary>
/// <param name="label">The label string.</param>
/// <returns>The UTF-8 encoded label bytes.</returns>
/// <exception cref="ArgumentException">Thrown when the label is empty or exceeds 64 UTF-8 bytes.</exception>
internal static byte[] ValidateAndEncodeLabel(string label)
{
    ArgumentException.ThrowIfNullOrEmpty(label);

    var encoded = Encoding.UTF8.GetBytes(label);

    if (encoded.Length > MaxLabelLength)
        throw new ArgumentException(
            $"Label UTF-8 encoding ({encoded.Length} bytes) exceeds maximum of {MaxLabelLength} bytes.",
            nameof(label));

    return encoded;
}

/// <summary>
///     Extracts the remaining management key retries from a 0x63Cx status word.
/// </summary>
/// <param name="sw">The status word from an APDU response.</param>
/// <returns>The number of remaining retries, or <c>null</c> if the SW is not a retry indicator.</returns>
internal static int? ExtractRetries(short sw) =>
    SWConstants.ExtractRetryCount(sw);

public void ValidateAndEncodeLabel_Exceeds64Bytes_ThrowsArgumentException()
{
    // 65 ASCII characters = 65 UTF-8 bytes
    var label = new string('a', 65);

    Assert.Throws<ArgumentException>(() => HsmAuthSession.ValidateAndEncodeLabel(label));
}

[Fact]
public void ValidateAndEncodeLabel_MultiByteUtf8_CountsByteLength()
{
    // Each CJK character is 3 UTF-8 bytes
    // 22 CJK chars = 66 bytes, exceeds 64
    var label = new string('\u4e00', 22);

    Assert.Throws<ArgumentException>(() => HsmAuthSession.ValidateAndEncodeLabel(label));
}

[Fact]
public void ValidateAndEncodeLabel_MultiByteUtf8Within64_Succeeds()
{
    // 21 CJK chars = 63 bytes, within limit
    var label = new string('\u4e00', 21);
    var result = HsmAuthSession.ValidateAndEncodeLabel(label);

    Assert.Equal(63, result.Length);
}

public class RetryExtractionTests
{
    [Theory]
    [InlineData(unchecked((short)0x63C0), 0)]
    [InlineData(unchecked((short)0x63C1), 1)]
    [InlineData(unchecked((short)0x63C5), 5)]
    [InlineData(unchecked((short)0x63C8), 8)]
    [InlineData(unchecked((short)0x63CF), 15)]
    public void ExtractRetries_ValidRetrySw_ReturnsCount(short sw, int expectedRetries)
    {
        var result = HsmAuthSession.ExtractRetries(sw);

        Assert.Equal(expectedRetries, result);
    }

    [Theory]
    [InlineData(unchecked((short)0x9000))]
    [InlineData(unchecked((short)0x6982))]
    [InlineData(unchecked((short)0x6300))]
    [InlineData(unchecked((short)0x6400))]
    [InlineData(unchecked((short)0x63D0))]
    public void ExtractRetries_NonRetrySw_ReturnsNull(short sw)
    {
        var result = HsmAuthSession.ExtractRetries(sw);

        Assert.Null(result);
    }
}

[Fact]
public void Dispose_ZerosAllKeyMaterial()
{
    // Arrange
    var response = new byte[48];
    for (var i = 0; i < 48; i++)
        response[i] = 0xFF;

    var keys = SessionKeys.Parse(response);

    // Capture the arrays owned by the parsed result so disposal zeroing is directly observable.
    byte[] sEnc = GetOwnedKeyBuffer(keys, "_sEnc");
    byte[] sMac = GetOwnedKeyBuffer(keys, "_sMac");
    byte[] sRmac = GetOwnedKeyBuffer(keys, "_sRmac");

    // Verify keys are non-zero before disposal
    Assert.Contains(sEnc, b => b != 0);
    Assert.Contains(sMac, b => b != 0);
    Assert.Contains(sRmac, b => b != 0);

    // Act
    keys.Dispose();

    // Assert - accessing after disposal should throw
    Assert.Throws<ObjectDisposedException>(() => _ = keys.SEnc);
    Assert.Throws<ObjectDisposedException>(() => _ = keys.SMac);
    Assert.Throws<ObjectDisposedException>(() => _ = keys.SRmac);
    Assert.All(sEnc, b => Assert.Equal(0, b));
    Assert.All(sMac, b => Assert.Equal(0, b));
    Assert.All(sRmac, b => Assert.Equal(0, b));
}

[Fact]
public async Task CalculateSessionKeysSymmetricAsync_WhenCredentialTouchPolicyIsUnknown_RequestsConservatively()
{
    var connection = CreateInitializedConnection(
        ListResponse("cred", HsmAuthAlgorithm.Aes128YubicoAuthentication, touchByte: 0x02, counter: 8),
        SessionKeyResponse());
    var prompt = new RecordingUserPresencePrompt();
    await using var session = await CreateSessionAsync(connection, prompt, new FirmwareVersion(5, 4, 3));

    using var keys = await CalculateSymmetricAsync(session, TestContext.Current.CancellationToken);

    AssertNotification(prompt, UserPresenceBasis.PolicyMayRequire, UserPresenceOutcome.Completed);
}

[Fact]
public async Task CalculateSessionKeysSymmetricAsync_WhenCredentialIsMissing_RemainsSilent()
{
    var connection = CreateInitializedConnection(
        ListResponse("other", HsmAuthAlgorithm.Aes128YubicoAuthentication, touchByte: 0x01, counter: 8),
        SessionKeyResponse());
    var prompt = new RecordingUserPresencePrompt();
    await using var session = await CreateSessionAsync(connection, prompt, new FirmwareVersion(5, 4, 3));

    using var keys = await CalculateSymmetricAsync(session, TestContext.Current.CancellationToken);

    Assert.Empty(prompt.Requests);
    Assert.Empty(prompt.Resolutions);
}

[Fact]
public async Task CalculateSessionKeysSymmetricAsync_WhenListFails_RequestsConservatively()
{
    var connection = CreateInitializedConnection([0x6A, 0x80], SessionKeyResponse());
    var prompt = new RecordingUserPresencePrompt();
    await using var session = await CreateSessionAsync(connection, prompt, new FirmwareVersion(5, 4, 3));

    using var keys = await CalculateSymmetricAsync(session, TestContext.Current.CancellationToken);

    AssertNotification(prompt, UserPresenceBasis.PolicyMayRequire, UserPresenceOutcome.Completed);
}
